SELECT page, ROUND((100 * SUM(CASE WHEN event_type = 'search' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_search, ROUND(STDDEV(duration_sec), 2) AS stddev_duration_sec, COUNT(CASE WHEN event_type = 'add_to_cart' THEN 1 END) AS add_to_cart_count FROM web_events WHERE session_id IN (9, 20, 37) AND session_id IN (7, 30) GROUP BY 1 ORDER BY add_to_cart_count DESC, pct_search, page LIMIT 3;
